# Final solution based on my analysis:
# - non-zero at all positions where r%2 == c%2 (same parity)
# - value 2 at Manhattan distance = source_pos when r%2 == 0 (upper half with even row)
# - value 1 at other even Manhattan distances

def transform(grid):
    width = len(grid[0])
    height = width
    source_val = None
    source_pos = None

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                source_val = grid[r][c]
                source_pos = c
                break
        if source_val:
            break

    if source_val is None:
        return [[0 for _ in range(width)] for _ in range(height)]

    center = (width - 1) // 2
    special_dist = source_pos

    out = [[0 for _ in range(width)] for _ in range(height)]

    for r in range(height):
        for c in range(width):
            # Only positions with same parity
            if (r % 2) != (c % 2):
                continue

            dist = abs(r - center) + abs(c - center)

            # Even distances only, not zero, not corners
            if dist % 2 == 0 and dist > 0 and dist < 2 * center:
                if dist == special_dist and r % 2 == 0:
                    out[r][c] = source_val
                else:
                    out[r][c] = 1

    return out

